exercises.starter:
function sumAll(arr) {
  // fold arr into its total with reduce
}

exercises.solution:
function sumAll(arr) {
  return arr.reduce((sum, x) => sum + x, 0)
}

exercises.starter:
function productAll(arr) {
  // multiply every element together with reduce
}

exercises.solution:
function productAll(arr) {
  return arr.reduce((product, x) => product * x, 1)
}

exercises.starter:
function maxOf(arr) {
  // reduce arr down to its largest value
}

exercises.solution:
function maxOf(arr) {
  return arr.reduce((max, x) => (x > max ? x : max))
}

exercises.starter:
function countPositive(arr) {
  // tally the positive numbers with reduce
}

exercises.solution:
function countPositive(arr) {
  return arr.reduce((count, x) => count + (x > 0 ? 1 : 0), 0)
}

exercises.starter:
function tally(arr) {
  // build a {value: count} object with reduce
}

exercises.solution:
function tally(arr) {
  return arr.reduce((counts, x) => {
    counts[x] = (counts[x] || 0) + 1
    return counts
  }, {})
}
